--
-- Table structure for table `waste`
--

DROP TABLE IF EXISTS `waste`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `waste` (
  `WasteID` int NOT NULL AUTO_INCREMENT,
  `Type` enum('Plastic','Glass','Organic','Paper','Electronic') NOT NULL,
  `WeightKg` decimal(5,2) NOT NULL,
  `WasteDate` date NOT NULL,
  `UserID` int DEFAULT NULL,
  `CollectionPointID` int DEFAULT NULL,
  PRIMARY KEY (`WasteID`),
  KEY `UserID` (`UserID`),
  KEY `CollectionPointID` (`CollectionPointID`),
  CONSTRAINT `waste_ibfk_1` FOREIGN KEY (`UserID`) REFERENCES `user` (`UserID`),
  CONSTRAINT `waste_ibfk_2` FOREIGN KEY (`CollectionPointID`) REFERENCES `collectionpoint` (`CollectionPointID`)
) ENGINE=InnoDB AUTO_INCREMENT=614 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

